import "server-only";
import { getPlan } from "@/config/plans";
import { publishedUrl } from "@/config/site";
import { gradeHtml } from "@/lib/site/grade";
import { invalidateSite } from "@/lib/site/hosting";
import { buildPublishedSite } from "@/lib/site/publish";
import { supabaseAdmin } from "@/lib/supabase/admin";
import type { FileMap, Project, SeoSnapshot } from "@/lib/types";

/**
 * Grades every published page with the same auditor as the free website grader. Sitemap and
 * robots.txt are generated by us; server speed is checked separately on the live site.
 */
function scoreBuild(files: FileMap, siteUrl: string, checkedAt: string): SeoSnapshot {
  const pages = Object.keys(files).filter((p) => p.endsWith(".html") && p !== "404.html");
  const results = pages.map((p) => ({
    page: p,
    result: gradeHtml(new URL(`${siteUrl}/${p === "index.html" ? "" : p.replace(/\.html$/, "")}`), files[p], {
      responseMs: 0,
      sitemap: Boolean(files["sitemap.xml"]),
      robotsOk: Boolean(files["robots.txt"]),
      robotsBlocksAll: /^\s*disallow:\s*\/\s*$/im.test(files["robots.txt"] ?? ""),
    }),
  }));
  const scores = results.map((r) => r.result.score);
  const issues = results.flatMap((r) => r.result.checks.filter((c) => c.status !== "pass").map((c) => ({ page: r.page, label: c.label, detail: c.detail, status: c.status as "warn" | "fail" })));
  return {
    score: scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0,
    min: scores.length ? Math.min(...scores) : 0,
    pages: scores.length,
    issues: issues.slice(0, 20),
    checkedAt,
  };
}

/** Builds the production copy of a project's current files and makes it live. */
export async function deployProject(project: Project, planId: string, files: FileMap = project.files) {
  const plan = getPlan(planId);
  const url = publishedUrl(project.slug, project.domain_verified ? project.custom_domain : null);
  const build = await buildPublishedSite({
    files,
    siteUrl: url,
    siteName: project.settings?.siteName ?? project.name,
    settings: project.settings ?? {},
    badge: plan.badge,
  });
  const now = new Date().toISOString();
  const seo = scoreBuild(build.files, url, now);
  const { error } = await supabaseAdmin()
    .from("projects")
    .update({
      published: true,
      published_at: now,
      published_files: build.files,
      published_source: files,
      settings: { ...project.settings, brand: build.brand, seo },
    })
    .eq("id", project.id);
  if (error) throw new Error(error.message);
  invalidateSite(project);
  return { url, warnings: build.warnings, publishedAt: now, seo };
}

/** Rebuilds an already-published site (after a domain change or plan change) without new content. */
export async function redeployPublished(projectId: string) {
  const admin = supabaseAdmin();
  const { data: project } = await admin.from("projects").select("*").eq("id", projectId).single();
  if (!project?.published || project.blocked) return;
  const { data: owner } = await admin.from("profiles").select("plan").eq("id", project.user_id).single();
  // Rebuild what was live, not any unpublished edits made since.
  await deployProject(project as Project, owner?.plan ?? "free", (project.published_source ?? project.files) as FileMap);
}
